// Node-RED Function node; same classroom contract as the TypeScript version.
// msg.payload: { start: "HH:MM", duration: integer, now: "HH:MM", blocked: boolean }
const bookings = Object.freeze([
  Object.freeze({ start: 600, end: 660, label: "CS101 Lecture" }),
  Object.freeze({ start: 900, end: 960, label: "Faculty Meeting" })
]);
const body = msg.payload && typeof msg.payload === "object" && !Array.isArray(msg.payload) ? msg.payload : {};
const parseTime = value => {
  if (typeof value !== "string") return null;
  const match = /^([01]?\d|2[0-3]):([0-5]\d)$/.exec(value.trim());
  return match ? Number(match[1]) * 60 + Number(match[2]) : null;
};
const start = parseTime(body.start);
const now = parseTime(body.now);
const rawDuration = body.duration;
const duration = typeof rawDuration === 'number' ? rawDuration :
  (typeof rawDuration === 'string' && rawDuration.trim() !== '' ? Number(rawDuration) : NaN);
const reply = (available, reasonCode, message, kind) => {
  msg.payload = {available,reasonCode,message,kind};
  msg.headers = {"Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store"};
  return msg;
};
if (start === null || now === null) return reply(false,'INVALID_TIME','Enter valid HH:MM start and current times.','validation');
if (!Number.isSafeInteger(duration) || duration <= 0) return reply(false,'INVALID_DURATION','Duration must be a positive whole number of minutes.','validation');
if (typeof body.blocked !== 'boolean') return reply(false,'INVALID_STATUS','Room blocked must be true or false.','validation');
const end = start + duration;
if (end > 1440) return reply(false,'INVALID_RANGE','The requested time range must end by 24:00.','validation');
if (start <= now) return reply(false,'PAST_START','Start must be later than the current demo time.','validation');
if (duration > 120) return reply(false,'DURATION_LIMIT','Duration must not exceed 120 minutes.','validation');
if (body.blocked === true) return reply(false,'ROOM_BLOCKED','Room B-204 is currently blocked.','unavailable');
if (bookings.some(b => start < b.end && b.start < end)) return reply(false,'OVERLAP','This request overlaps an existing booking.','unavailable');
return reply(true,'AVAILABLE','Room B-204 is available for the requested interval.','available');
